escription\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [819, 1747, 1396, 1914], \"page_id\": 50}], \"content\": \"redeemed at the purchase price only. Series C notes were first offered for sale on September 14, 1942. Interest on those notes accrues each month on a graduated scale, and is equivalent to a yield of approximately 1.07 percent per annum if held to maturity. The amounts which may be turned in on taxes is unlimited. If not presented in payment of taxes, the notes will be redeemable at par and accrued interest, either at maturity or, on 30 days' notice, during and after the sixth month after the month of issue.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [785, 1910, 828, 1960], \"page_id\": 50}], \"content\": null, \"description\": null, \"id\": 10, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [828, 1912, 1428, 1989], \"page_id\": 50}], \"content\": \"Sale of Tax Series Treasury notes began in August 1941. Sales of Series B notes have been reduced by $43.6 millions, the amount of notes exchanged during the month of September 1942. Those exchanges have been included in the sales of Series C notes.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [743, 72, 775, 100], \"page_id\": 51}], \"content\": \"41\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [433, 140, 1081, 172], \"page_id\": 51}], \"content\": \"Sales of Tax Series Treasury Notes - (Continued)\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [338, 199, 1180, 229], \"page_id\": 51}], \"content\": \"Table 2.- Sales Reported by Series, Classified by Denomination\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [66, 281, 1445, 421], \"page_id\": 51}], \"content\": \"<table><tr><th rowspan=\\\"2\\\">Fiscal year or month</th><th colspan=\\\"10\\\">Sales in millions of dollars at par</th><th colspan